function CatEggComponent:InitialDojo(data)
    self._playerCatId2Dojo = {}
    self._catId2Dojo = {}
    for i, v in pairs(data) do
        ---@type CatEggDojo
        local dojo = CatEggDojo.New()
        dojo:FillData(v)
        self._playerCatId2Dojo[checkNumber(dojo.id)] = dojo
        self._catId2Dojo[checkNumber(dojo.catId)] = dojo
    end
end

---DrawCatDrawRewards
---@param data table
function CatEggComponent:DrawCatDrawRewards(data)
    for i, v in pairs(data) do
        ---@type CatEggDojo
        local dojo = CatEggDojo.New()
        dojo:FillData(v)
        self:DrawCatDrawReward(dojo)
    end
end

---DrawCatDrawReward
---@param dojo CatEggDojo
function CatEggComponent:DrawCatDrawReward(dojo)
    self._playerCatId2Dojo[checkNumber(dojo.id)] = dojo
    self._catId2Dojo[checkNumber(dojo.catId)] = dojo
    -- 图鉴增加已收集 猫球
    ---@type IllustratedHandbookComponent
    local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
    illustratedHandbookComp:CheckHandbookStorage(Constants.HandbookCollectionType.CAT_BALL, dojo.catId)
    illustratedHandbookComp:CheckHandbookCatBallRedPoint()

    self:SetCatBallNewFlag(dojo.id)
end

