---RecycleCatEgg
---回收猫球
---@param ids table or number
function CatEggComponent:RecycleCatEgg(ids)
    if type(ids) == 'table' then
        for _, id in pairs(ids) do
            local dojo = self._playerCatId2Dojo[checkNumber(id)]
            self._playerCatId2Dojo[checkNumber(id)] = nil
            self._catId2Dojo[checkNumber(dojo.catId)] = nil
        end
    else
        ---单一数字
        local dojo = self._playerCatId2Dojo[checkNumber(ids)]
        self._playerCatId2Dojo[checkNumber(ids)] = nil
        self._catId2Dojo[checkNumber(dojo.catId)] = nil
    end
    ----数据发生的变化
    Events.Broadcast(Constants.EventNames.EVENT_CAT_EGG_DATA_CHANGED)
end

